import re

def parse_labeled(text,label):
 m=re.search(re.escape(label)+r' \((\d+)x(\d+)\):\n',text)
 if not m: raise ValueError(label)
 h,w=map(int,m.groups()); rows=[]
 for line in text[m.end():].splitlines():
  vals=[int(x) for x in line.split() if x.isdigit()]
  if len(vals)==w: rows.append(vals)
  if len(rows)==h: return rows
 raise ValueError((label,len(rows)))
