code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # The color-4 object is the reference pattern. Keep its exact orientation.
    ref = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 4]
    if not ref:
        return [row[:] for row in grid]
    r0, c0 = min(r for r, c in ref), min(c for r, c in ref)
    shape = {(r-r0, c-c0) for r, c in ref}
    maxr, maxc = max(r for r, c in shape), max(c for r, c in shape)

    out = [row[:] for row in grid]
    colors = sorted({v for row in grid for v in row if v not in (1, 4)})
    for color in colors:
        pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color]

        def placements_for(p):
            result = []
            for dr in range(max(0, p[0]-maxr), min(h-maxr, p[0])+1):
                for dc in range(max(0, p[1]-maxc), min(w-maxc, p[1])+1):
                    if (p[0]-dr, p[1]-dc) in shape:
                        result.append((dr, dc))
            return result

        # Pixels belong to one copy if a translated reference can contain them both.
        adj = {p: set() for p in pts}
        for i, p in enumerate(pts):
            poss = set(placements_for(p))
            for q in pts[i+1:]:
                if poss.intersection(placements_for(q)):
                    adj[p].add(q); adj[q].add(p)
        groups = []
        unseen = set(pts)
        while unseen:
            stack = [unseen.pop()]; group = set(stack)
            while stack:
                p = stack.pop()
                for q in adj[p] & unseen:
                    unseen.remove(q); group.add(q); stack.append(q)
            groups.append(group)

        for group in groups:
            candidates = [(dr, dc) for dr in range(h-maxr) for dc in range(w-maxc)
                          if all((r-dr, c-dc) in shape for r, c in group)]
            if not candidates:
                continue
            # In valid instances the seed fragment determines one placement.
            # If there is a tie, prefer the placement whose origin is nearest the seed bbox.
            gr0, gc0 = min(r for r,c in group), min(c for r,c in group)
            dr, dc = min(candidates, key=lambda t: abs(t[0]-gr0)+abs(t[1]-gc0))
            for sr, sc in shape:
                rr, cc = dr+sr, dc+sc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = color
    return out
'''
